        "저장소 관리자 저장소 생성에서 스토리지 풀 생성을 시작합니다. RAID 유형(SHR·RAID 1 등)을 고르고 디스크를 선택합니다. 이어서 볼륨 생성으로 넘어가면 파일 시스템 항목에 Btrfs 와 ext4 가 나와요. 여기서 Btrfs 를 고릅니다. 모델에 따라 이 선택지가 없고 ext4 만 나오는 기종이 있습니다. 그 기종은 스냅샷 기능을 쓸 수 없으니 구매 전에 확인할 항목입니다.",
        "볼륨을 만든 뒤 켜야 효과가 납니다. 먼저 Snapshot Replication 패키지를 설치합니다. 스냅샷에서 공유 폴더를 고른 뒤 일정과 보존 정책을 잡아요. 회사 자료는 업무 시간에 매시간, 보존은 며칠에서 몇 주 단위가 흔합니다. 다음은 제어판 공유 폴더 편집 고급 탭의 데이터 무결성 보호(체크섬) 옵션입니다. 폴더를 새로 만들 때 켜야 하며 이미 자료가 든 폴더에는 대개 나중에 켤 수 없습니다. 공유 폴더 할당량도 Btrfs 에서만 동작합니다.",
