        "랜섬웨어 대비에서 놓치기 쉬운 점은 관리자 계정이에요. 스냅샷은 대개 읽기 전용이라 암호화되지 않습니다. 그런데 DSM 관리자 계정이 뚫리면 공격자가 스냅샷 자체를 지울 수 있습니다. 관리자 계정에 2단계 인증을 걸고 admin 이름의 계정은 비활성으로 둡니다. 이것이 스냅샷을 지키는 조건입니다. DSM 버전에 따라 정해진 기간 동안 삭제할 수 없게 잠그는 스냅샷 옵션도 있어요.",
