        "Cloud Sync는 두 곳을 같게 만드는 도구이지 시점을 남기는 도구가 아닙니다. 양방향으로 두고 클라우드 쪽에서 폴더를 치우면 NAS에서도 같은 파일이 지워져요. 랜섬웨어로 NAS 파일이 암호화되면 어떻게 될까요? 그 암호화된 파일이 클라우드로 그대로 올라가 멀쩡한 사본을 덮습니다. 이전 시점이 필요하면 Cloud Sync 대신 Hyper Backup으로 클라우드 백업 작업을 잡습니다. 아니면 NAS 쪽에 Snapshot Replication을 같이 둡니다.",
