        "가장 흔한 실수는 팀 폴더 전체를 노트북에 동기화하는 것입니다. NAS에 수백 GB가 있으면 노트북이 며칠 동안 내려받다 디스크가 꽉 차요. 동기화 작업을 편집해 필요한 하위 폴더만 남깁니다. 아니면 클라이언트의 주문형 동기화 기능을 켜서 열어 본 파일만 내려받게 둡니다. 이미 가득 찬 노트북은 동기화 작업을 잠시 멈추고 폴더 범위를 줄인 뒤 다시 켭니다.",
