        "그다음 제어판 공유 폴더에서 폴더를 만들거나 편집으로 열고 권한 항목으로 갑니다. 위쪽 목록을 로컬 사용자에서 로컬 그룹으로 바꾸면 방금 만든 부서 그룹이 나옵니다. 그 부서에는 읽기/쓰기, 다른 부서에는 접근 없음을 체크합니다. 여기서 사람 이름은 고르지 않는 것이 원칙입니다. 대표나 관리자만 여는 폴더는 관리자 그룹만 읽기/쓰기로 두고 나머지 그룹 전부에 접근 없음을 줍니다.",
        "권한이 겹칠 때의 우선순위를 알아 두면 헷갈리지 않아요. 접근 없음이 가장 세고, 그다음이 읽기/쓰기, 마지막이 읽기 전용입니다. 어떤 사람이 영업 그룹으로는 읽기/쓰기인데 다른 그룹으로 접근 없음이면 결과는 접근 없음입니다. 폴더 편집 화면에는 권한 없는 사용자에게 폴더 자체를 숨기는 항목도 있어요. 이걸 켜면 다른 부서 직원의 탐색기에는 그 폴더가 아예 보이지 않습니다."
