        "맥은 Finder 에서 이동 서버에 연결을 엽니다. smb://192.168.0.10 을 넣은 뒤 연결을 누릅니다. 등록 사용자로 NAS 계정을 넣고 키체인에 저장을 체크하면 다음부터 비밀번호를 묻지 않아요. 볼륨 목록에서 공유 폴더를 고르면 데스크탑에 붙습니다. 재부팅 뒤에도 자동으로 붙게 하려면 시스템 설정 일반 로그인 항목에 그 볼륨을 끌어다 넣습니다.",
        "이름으로 적었는데 어느 날 못 찾는 경우가 있어요. 윈도우가 이름을 푸는 방식이 네트워크 환경마다 다르기 때문입니다. DSM 7 은 제어판 파일 서비스 SMB 의 고급 설정에서 WS-Discovery 를 켤 수 있습니다. 그러면 탐색기의 네트워크 목록에 NAS 가 나타나요. 그래도 드라이브로 고정할 주소는 IP 로 적는 편이 확실합니다. 대신 그 IP 가 바뀌지 않도록 제어판 네트워크 네트워크 인터페이스에서 수동 IP 를 줍니다. 아니면 공유기에서 예약해 둡니다."
