  "syn-prevent-delete": [
    {
      "h": "DSM 7에서 세 겹을 실제로 잡는 순서",
      "body": [
        "첫 겹은 권한이에요. 제어판 공유 폴더에서 해당 폴더를 고르고 편집을 눌러 권한 항목으로 갑니다. 목록을 로컬 그룹으로 바꿔 직원 그룹에 읽기/쓰기를 줍니다. 그 줄의 사용자 정의 항목을 열면 세부 권한이 나옵니다. 여기서 삭제와 하위 폴더 및 파일 삭제 두 항목만 끕니다. 나머지 읽기와 쓰기 항목은 그대로 둡니다. 관리자 그룹은 손대지 않아야 나중에 정리할 수 있습니다.",
        "두 번째 겹은 휴지통입니다. 같은 편집 화면의 첫 항목에 휴지통 활성화가 있어요. 켜면서 관리자에게만 접근 제한도 함께 켜 두면 직원이 휴지통을 뒤져 비우는 일을 막을 수 있습니다. 휴지통은 공유 폴더마다 따로 켜야 하므로 폴더가 여러 개면 하나씩 확인합니다. 지운 파일은 File Station에서 그 공유 폴더 안의 휴지통 전용 숨김 폴더에 들어갑니다. 여기서 원래 자리로 복사해 되돌립니다.",
        "세 번째 겹은 스냅샷이에요. Snapshot Replication을 설치하고 스냅샷 항목에서 공유 폴더를 골라 일정을 잡습니다. 평일 낮에는 한 시간마다, 밤에는 하루 한 번 정도가 사무실에 무난합니다. 보존 개수를 정해 오래된 것은 자동으로 지워지게 둡니다. 되돌릴 때는 복구 항목에서 시점을 고른 뒤 폴더 전체를 되돌립니다. 아니면 File Station에서 파일 하나만 꺼냅니다. 스냅샷은 볼륨이 Btrfs일 때만 되므로 저장소 관리자에서 볼륨 형식을 먼저 확인합니다."
      ]
    },
    {
      "h": "삭제 권한을 뺐더니 저장이 안 된다는 전화가 오는 이유",
      "body": [
        "삭제 권한을 빼면 생각지 못한 곳에서 걸립니다. 엑셀이나 워드는 저장할 때 임시 파일을 만든 뒤 원본을 지우고 이름을 바꾸는 방식을 많이 써요. 삭제가 막히면 기존 파일에 덮어쓰기가 실패하거나 임시 파일이 폴더에 남습니다. 파일 이름 바꾸기와 다른 폴더로 옮기기도 삭제로 취급되어 막힙니다. 이 증상이 나오면 권한을 다시 풀고 휴지통과 스냅샷 두 겹만으로 지키는 쪽이 현실적입니다. 실제로 많은 사무실이 권한은 읽기/쓰기 그대로 두고 휴지통과 스냅샷으로 막아요.",
        "휴지통에서 흔한 실수는 비우기 주기를 안 정해 두는 것입니다. 지운 파일이 계속 쌓여 용량을 차지하다 관리자가 한꺼번에 비우면 어떻게 될까요? 그 안에 아직 필요한 파일이 있을 수 있습니다. 제어판의 예약 작업에서 사용자 정의 스크립트로 오래된 휴지통 파일을 지우는 작업을 만듭니다. 보관 기간을 30일 정도로 잡아 두면 그 기간이 지난 파일만 자동으로 정리돼요. 반대로 휴지통을 켜기 전에 지운 파일은 휴지통에 없으므로 스냅샷이나 백업에서 찾아야 합니다.",
        "스냅샷에서 흔한 실수는 랜섬웨어까지 막아 준다고 믿고 백업을 미루는 것입니다. 스냅샷은 같은 NAS의 같은 디스크에 있어요. 디스크 고장이나 NAS 도난에는 소용이 없습니다. 실수 삭제는 스냅샷, 장비 사고는 Hyper Backup으로 나누어 두어야 합니다. 스냅샷 보존 개수를 너무 크게 잡으면 볼륨이 차서 새 파일 저장이 막힐 수 있습니다. 저장소 관리자에서 스냅샷이 차지하는 용량을 가끔 확인합니다."
      ]
    }
  ],
