      "h": "NAS 쪽 설정 순서(SMB 기준)",
      "body": [
        "제어판 공유 폴더에서 생성 버튼으로 스캔 전용 폴더를 만듭니다. 이름은 scan처럼 영문으로 짧게 두는 것이 복합기 입력에 편합니다. 만들 때 휴지통 활성화를 켜 두면 잘못 지운 스캔본을 되살릴 수 있습니다.",
        "제어판 사용자 및 그룹에서 복합기가 쓸 전용 계정을 만듭니다. 권한 탭에서 scan 폴더만 읽기/쓰기로 주고 나머지 공유 폴더는 접근 없음으로 둡니다. 애플리케이션 탭에서는 파일 서비스 외의 앱 권한을 뺍니다. 비밀번호는 복합기 조작 패널에서 입력하기 쉬운 영문과 숫자 조합으로 정하세요. 관리자 계정을 복합기에 넣는 것은 금물입니다.",
        "제어판 파일 서비스에서 SMB가 켜져 있는지 보고, 고급 설정의 최소 SMB 프로토콜 버전을 확인합니다. 오래된 복합기는 SMB2 이상을 지원하지 않는 경우가 있어요. 그렇다고 SMB1을 여는 것은 보안상 권하지 않습니다. FTP로 바꾸거나 복합기 펌웨어를 올리는 쪽이 나아요. NAS의 IP는 제어판 네트워크 네트워크 인터페이스에서 수동(고정)으로 잡습니다. 그래야 복합기에 넣은 주소가 바뀌지 않아요.",
        "복합기 쪽에서는 주소록이나 스캔 전송 설정을 엽니다. 서버 경로(NAS의 IP 주소와 폴더 이름 scan)를 넣습니다. 계정과 비밀번호를 넣고 테스트 전송을 해 보세요. 성공하면 File Station에서 PDF가 들어왔는지 확인합니다. 마지막으로 그 폴더를 Snapshot Replication 스냅샷 대상에 넣습니다. Hyper Backup 대상에도 넣으면 스캔본이 보호돼요."
      ],
